// Draws the program icon (a scope reticle over a valley at dusk) and writes
// electron/icon.png (256 px, window icon) and electron/icon.ico (16-256 px, the .exe icon).
// Generated by this code, no image files; run `node scripts/make-icon.mjs` after changing it.
import fs from 'node:fs';
import zlib from 'node:zlib';

const ACCENT = [217, 164, 65], LIGHT = [233, 238, 232], RED = [255, 90, 60];

const mix = (a, b, t) => a + (b - a) * t;
const smooth = (e0, e1, x) => { const t = Math.min(1, Math.max(0, (x - e0) / (e1 - e0))); return t * t * (3 - 2 * t); };

// colour of the icon at (u, v) in 0..1 (v down), with antialiasing width `aa`: [r, g, b, a]
function shade(u, v, aa, small) {
  // rounded square
  const qx = Math.abs(u - 0.5) - 0.5 + 0.17, qy = Math.abs(v - 0.5) - 0.5 + 0.17;
  const box = Math.hypot(Math.max(qx, 0), Math.max(qy, 0)) + Math.min(Math.max(qx, qy), 0) - 0.17;
  const inside = 1 - smooth(-aa, aa, box);
  if (inside <= 0) return [0, 0, 0, 0];
  // sky: dusk gradient
  let c = [mix(52, 18, v), mix(66, 27, v), mix(70, 24, v)];
  // two ridges of the valley, the far one lighter
  const far = 0.6 - 0.12 * Math.exp(-((u - 0.28) ** 2) / 0.02) - 0.08 * Math.exp(-((u - 0.78) ** 2) / 0.03);
  const near = 0.74 - 0.1 * Math.exp(-((u - 0.62) ** 2) / 0.025) + 0.04 * Math.sin(u * 9);
  const kf = smooth(far - aa, far + aa, v), kn = smooth(near - aa, near + aa, v);
  c = c.map((x, i) => mix(x, [34, 52, 38][i], kf));
  c = c.map((x, i) => mix(x, [16, 24, 18][i], kn));
  // reticle
  const dx = u - 0.5, dy = v - 0.47, r = Math.hypot(dx, dy);
  const R = 0.3, w = small ? 0.075 : 0.045;
  const ring = 1 - smooth(w / 2 - aa, w / 2 + aa, Math.abs(r - R));
  const lw = small ? 0.06 : 0.032, gap = small ? 0.09 : 0.075, len = R + 0.1;
  const arm = (a, b) => (1 - smooth(lw / 2 - aa, lw / 2 + aa, Math.abs(a))) * smooth(gap - aa, gap + aa, Math.abs(b)) * (1 - smooth(len - aa, len + aa, Math.abs(b)));
  const cross = Math.max(arm(dx, dy), arm(dy, dx));
  const ink = Math.max(ring, cross);
  c = c.map((x, i) => mix(x, LIGHT[i], ink * 0.95));
  // a warm rim on the ring's lower half
  c = c.map((x, i) => mix(x, ACCENT[i], ring * smooth(0.0, 0.25, dy) * 0.8));
  const dot = 1 - smooth((small ? 0.05 : 0.032) - aa, (small ? 0.05 : 0.032) + aa, r);
  c = c.map((x, i) => mix(x, RED[i], dot));
  return [c[0], c[1], c[2], 255 * inside];
}

function render(size) {
  const ss = 4, px = Buffer.alloc(size * size * 4);
  const small = size <= 32;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const acc = [0, 0, 0, 0];
      for (let j = 0; j < ss; j++) for (let i = 0; i < ss; i++) {
        const s = shade((x + (i + 0.5) / ss) / size, (y + (j + 0.5) / ss) / size, 0.6 / size, small);
        const a = s[3] / 255;
        acc[0] += s[0] * a; acc[1] += s[1] * a; acc[2] += s[2] * a; acc[3] += a;
      }
      const o = (y * size + x) * 4, a = acc[3];
      px[o] = a ? Math.round(acc[0] / a) : 0;
      px[o + 1] = a ? Math.round(acc[1] / a) : 0;
      px[o + 2] = a ? Math.round(acc[2] / a) : 0;
      px[o + 3] = Math.round((a / (ss * ss)) * 255);
    }
  }
  return px;
}

const CRC = new Uint32Array(256).map((_, n) => { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; return c >>> 0; });
const crc32 = (buf) => { let c = 0xffffffff; for (const b of buf) c = CRC[(c ^ b) & 0xff] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
function chunk(type, data) {
  const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
  const td = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(td));
  return Buffer.concat([len, td, crc]);
}
function png(size) {
  const px = render(size);
  const raw = Buffer.alloc(size * (size * 4 + 1));
  for (let y = 0; y < size; y++) px.copy(raw, y * (size * 4 + 1) + 1, y * size * 4, (y + 1) * size * 4);
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(size, 0); ihdr.writeUInt32BE(size, 4); ihdr[8] = 8; ihdr[9] = 6;
  return Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', ihdr), chunk('IDAT', zlib.deflateSync(raw, { level: 9 })), chunk('IEND', Buffer.alloc(0))]);
}

const sizes = [16, 24, 32, 48, 64, 128, 256];
const pngs = sizes.map(png);
const head = Buffer.alloc(6 + 16 * sizes.length);
head.writeUInt16LE(0, 0); head.writeUInt16LE(1, 2); head.writeUInt16LE(sizes.length, 4);
let offset = head.length;
sizes.forEach((s, i) => {
  const e = 6 + i * 16;
  head[e] = s >= 256 ? 0 : s; head[e + 1] = s >= 256 ? 0 : s;
  head.writeUInt16LE(1, e + 4); head.writeUInt16LE(32, e + 6);
  head.writeUInt32LE(pngs[i].length, e + 8); head.writeUInt32LE(offset, e + 12);
  offset += pngs[i].length;
});
fs.writeFileSync(new URL('../electron/icon.ico', import.meta.url), Buffer.concat([head, ...pngs]));
fs.writeFileSync(new URL('../electron/icon.png', import.meta.url), pngs[sizes.indexOf(256)]);
console.log('electron/icon.png and electron/icon.ico written');
